function applyTrialCopy(locale){const c=TRIAL_COPY[locale]||TRIAL_COPY.en;document.querySelectorAll('[data-trial-copy="plan"]').forEach(x=>x.textContent=c.plan);document.querySelectorAll('[data-trial-copy="pricing"]').forEach(x=>x.innerHTML=c.pricing);document.querySelectorAll('[data-trial-copy="checkout"]').forEach(x=>x.innerHTML=c.checkout)}
function canonicalLocale(x){x=String(x||'').trim();const l=LANGS.find(v=>v[0].toLowerCase()===x.toLowerCase());if(l)return l[0];const short=x.toLowerCase().split('-')[0];return LANGS.find(v=>v[0].toLowerCase().split('-')[0]===short)?.[0]||'en'}
function detect(){const q=new URLSearchParams(location.search).get('lang');if(q)return canonicalLocale(q);try{const s=localStorage.getItem(STORE);if(s)return canonicalLocale(s)}catch{}return 'en'}
function style(){if(document.getElementById(ID+'-css'))return;const s=document.createElement('style');s.id=ID+'-css';s.textContent=`[data-cs-untranslated]{display:none!important}.csLang{position:relative}.csLangBtn{border:1px solid #343443;background:#111119;color:#f5f4f8;border-radius:999px;padding:8px 10px;font-size:11px;font-weight:850;min-width:48px}.csLangMenu{display:none;position:absolute;right:0;top:calc(100% + 8px);width:210px;max-height:min(430px,70vh);overflow:auto;background:#111119;border:1px solid #343443;border-radius:17px;padding:7px;box-shadow:0 24px 70px #000b;z-index:120}.csLang.open .csLangMenu{display:grid}.csLangOpt{border:0;background:transparent;color:#d5d3dd;border-radius:11px;padding:9px 10px;text-align:left;font-size:11px;display:flex;justify-content:space-between;gap:10px}.csLangOpt:hover,.csLangOpt.active{background:#211725;color:#fff}.csLangOpt span:last-child{color:#77768a;font-size:9px}.csLangMobile{display:none}@media(max-width:940px){.csLangDesktop{display:none}.csLangMobile{display:block;margin-left:auto}.navin{gap:10px}}[dir="rtl"] .csLangMenu{right:auto;left:0}[dir="rtl"] .csLangOpt{text-align:right}`;document.head.appendChild(s)}
function translateText(locale){const dict=T[locale]||{};const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){if(!n.nodeValue?.trim())return NodeFilter.FILTER_REJECT;const p=n.parentElement;if(!p||['SCRIPT','STYLE','TEXTAREA','OPTION'].includes(p.tagName))return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT}});const nodes=[];while(w.nextNode())nodes.push(w.currentNode);for(const n of nodes){if(!n.__csOriginal)n.__csOriginal=n.nodeValue;const base=n.__csOriginal.trim();if(locale==='es'){n.nodeValue=n.__csOriginal;continue}const tr=locale==='en'?(dict[base]||EN_FULL[base]):dict[base];if(tr){n.nodeValue=n.__csOriginal.replace(base,tr);n.parentElement?.removeAttribute('data-cs-untranslated')}else{const tech=/^(?:CloudSales|Cloudy|AgentCloud|CRM|API|SEO|PWA|OAuth|WhatsApp|Meta|Google|TikTok|LinkedIn|YouTube|Stripe|HighLevel|Salesforce|HubSpot|Zoho CRM|Pipedrive|monday CRM|Freshsales|Close|Copper|Twenty|Basic|Pro|Premium|CloudCo|Junk Lead Firewall|WAF|Conversion API|Web Events|CRM Events|Data Signals|Attribution|Audiences|USD|Academy)$/i.test(base);if(!tech&&/[A-Za-zÁÉÍÓÚÜÑáéíóúüñ¿¡]/.test(base)&&base.split(/\s+/).length>1)n.parentElement?.setAttribute('data-cs-untranslated',locale)}}}
function meta(locale){const desc={es:'CloudSales mejora la calidad de tus leads, reduce junk leads y te permite controlar tu CRM, conversaciones, citas y pipeline desde la palma de tu mano.',en:'CloudSales improves lead quality, reduces junk leads, and lets you manage your CRM, conversations, appointments, and pipeline from your phone.',fr:'CloudSales améliore la qualité des prospects, réduit les faux leads et vous permet de gérer CRM, conversations, rendez-vous et pipeline depuis votre téléphone.',it:'CloudSales migliora la qualità dei lead, riduce i lead spazzatura e ti permette di gestire CRM, conversazioni, appuntamenti e pipeline dal telefono.','pt-BR':'CloudSales melhora a qualidade dos leads, reduz leads ruins e permite controlar CRM, conversas, reuniões e pipeline pelo celular.',de:'CloudSales verbessert die Lead-Qualität, reduziert Junk-Leads und ermöglicht CRM, Gespräche, Termine und Pipeline vom Smartphone aus.','ar-AE':'يحسن CloudSales جودة العملاء المحتملين ويقلل العملاء غير الصالحين ويتيح إدارة CRM والمحادثات والمواعيد وخط المبيعات من الهاتف.',ru:'CloudSales повышает качество лидов, сокращает мусорные лиды и позволяет управлять CRM, диалогами, встречами и воронкой с телефона.',he:'CloudSales משפר את איכות הלידים, מפחית לידים לא רלוונטיים ומאפשר לנהל CRM, שיחות, פגישות ופייפליין מהטלפון.','zh-CN':'CloudSales 提升销售线索质量、减少垃圾线索，并可通过手机管理 CRM、对话、预约和销售管道。',ja:'CloudSalesはリード品質を高め、無効なリードを減らし、CRM・会話・商談・パイプラインをスマートフォンから管理できます。'};document.querySelector('meta[name="description"]')?.setAttribute('content',desc[locale]||desc.es);document.title=locale==='es'?'CloudSales — IA trabajando por ti, mejores prospectos y control desde tu celular':'CloudSales — AI working for you, better leads and mobile control'}
function menu(locale){const html=LANGS.map(([code,short,name])=>`<button class="csLangOpt ${code===locale?'active':''}" data-lang="${code}"><b>${name}</b><span>${short}</span></button>`).join('');return `<div class="csLang"><button class="csLangBtn" aria-label="Language">${LANGS.find(x=>x[0]===locale)?.[1]||'EN'} ▾</button><div class="csLangMenu">${html}</div></div>`}
function mount(locale){document.querySelectorAll('.csLang').forEach(x=>x.remove());const links=document.querySelector('.navlinks');if(links){const d=document.createElement('div');d.className='csLangDesktop';d.innerHTML=menu(locale);links.insertBefore(d,links.firstChild)}const navin=document.querySelector('.navin');if(navin){const m=document.createElement('div');m.className='csLangMobile';m.innerHTML=menu(locale);navin.appendChild(m)}document.querySelectorAll('.csLangBtn').forEach(b=>b.onclick=e=>{e.stopPropagation();b.closest('.csLang')?.classList.toggle('open')});document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLocale(b.dataset.lang));if(!document.documentElement.dataset.csLangCloseBound){document.documentElement.dataset.csLangCloseBound='1';document.addEventListener('click',e=>{if(!e.target.closest('.csLang'))document.querySelectorAll('.csLang.open').forEach(x=>x.classList.remove('open'))},true)}}
function attrs(locale){const d=T[locale]||{},tr=x=>locale==='es'?x:(d[x]||EN_FULL[x]||x);const email=document.getElementById('cemail');if(email){if(!email.dataset.csOrigPlaceholder)email.dataset.csOrigPlaceholder=email.getAttribute('placeholder')||'';email.setAttribute('placeholder',tr(email.dataset.csOrigPlaceholder))}const err=document.getElementById('cerr');if(err&&!err.dataset.csI18nObs){err.dataset.csI18nObs='1';new MutationObserver(()=>{const v=err.textContent||'';if(locale==='es')return;for(const [a,b] of Object.entries({...EN_FULL,...d})){if(v===a){err.textContent=b;return}if(a.endsWith(': ')&&v.startsWith(a)){err.textContent=b+v.slice(a.length);return}}}).observe(err,{childList:true,characterData:true,subtree:true})}}
function setLocale(x){const locale=canonicalLocale(x);try{localStorage.setItem(STORE,locale)}catch{}const u=new URL(location.href);u.searchParams.set('lang',locale);history.replaceState(null,'',u);apply(locale)}
function apply(locale){document.documentElement.lang=locale;document.documentElement.dir=RTL.has(locale)?'rtl':'ltr';translateText(locale);meta(locale);mount(locale);document.documentElement.dataset.csLocale=locale;attrs(locale);applyTrialCopy(locale);document.documentElement.classList.remove('cs-i18n-pending');window.dispatchEvent(new CustomEvent('cloudsales:locale',{detail:{locale}}))}
function patchHostedCheckout(){
  const start=document.getElementById('cstart'),email=document.getElementById('cemail'),mount=document.getElementById('stripeMount'),err=document.getElementById('cerr');
  if(!start||!email||!mount||!err||start.dataset.csHostedPatched==='1')return;
  let item='';
  document.querySelectorAll('.buy[data-item]').forEach(b=>b.addEventListener('click',()=>{item=b.dataset.item||''}));
  start.dataset.csHostedPatched='1';
  start.onclick=async()=>{
    const mail=email.value.trim();if(!mail||!item){err.textContent='Escribe un correo válido.';return}
    err.textContent='Preparando checkout…';start.disabled=true;
    try{
      const ref=new URL(location.href).searchParams.get('ref')||localStorage.getItem('cloudsales_ref')||'';if(ref)localStorage.setItem('cloudsales_ref',ref);
      const r=await fetch('https://fkahaqprzgcimgyathqx.supabase.co/functions/v1/stripe-checkout-start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({item_key:item,email:mail,affiliate_code:ref})});
      const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||d.error||'checkout_error');
      if(d.checkout_url){location.assign(d.checkout_url);return}
      if(!d.client_secret||!d.publishable_key)throw Error('checkout_not_available');
      const stripe=Stripe(d.publishable_key),instance=await stripe.initEmbeddedCheckout({clientSecret:d.client_secret});
      document.getElementById('emailrow').style.display='none';err.textContent='';instance.mount('#stripeMount');
    }catch(e){err.textContent='No pudimos abrir el checkout: '+(e?.message||'error');start.disabled=false}
  };
}
